{
  "groups": [
    {
      "group_id": "vulnerable_renters",
      "rule": "occupancy_type == 'rental' and credit_score_band == 'below_600'",
      "rationale": "Borrowers with low credit scores who do not occupy their property are likely to prioritize liquidity over retention."
    },
    {
      "group_id": "rate_sensitive_fixed_short",
      "rule": "rate_type == 'fixed' and origination_year >= 2021 and mortgage_rate_pct > 5.0",
      "rationale": "Borrowers with high fixed rates from recent vintages are highly motivated to seek competitive refinancing options."
    },
    {
      "group_id": "stressed_variable_holders",
      "rule": "rate_type == 'variable' and credit_utilization_pct > 45.0 and mortgage_rate_pct > 5.0",
      "rationale": "Variable rate borrowers experiencing high credit utilization feel the cumulative pressure of rising payments."
    },
    {
      "group_id": "life_event_impacted",
      "rule": "life_event_6m == True and life_event_type != 'none'",
      "rationale": "Major personal transitions significantly disrupt long-term mortgage inertia and trigger active lender shopping."
    },
    {
      "group_id": "wealthy_stable_owners",
      "rule": "credit_score_band == '720_plus' and has_investments == True and insured_flag == False",
      "rationale": "High-net-worth individuals with strong credit profiles are prime targets for competitor acquisition efforts."
    },
    {
      "group_id": "high_burden_families",
      "rule": "n_children >= 3 and household_income_cad < 75000",
      "rationale": "Families with many dependents and modest income have low tolerance for payment increases."
    },
    {
      "group_id": "senior_low_mobility",
      "rule": "primary_borrower_age >= 60 and employment_status == 'retired'",
      "rationale": "Retired homeowners typically prioritize stability and have lower propensity to switch lenders."
    },
    {
      "group_id": "digital_native_savers",
      "rule": "channel == 'digital' and has_savings == True and has_advisor == False",
      "rationale": "Independent digital users with available liquidity are comfortable managing their own mortgage products."
    }
  ]
}
